package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;

class FrequencyCorrectionConcurrencyTests extends FrequencyCorrectionTestSupport {
    @RepeatedTest(2) void ownerAndAdminSameVersionProduceExactlyOneAudit() throws Exception {var a=fact(SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(3),"08:00");long count=audits.count();assertEquals(new RaceResult(1,1),race("E4-owner-admin",List.of(()->businessStatus(correct(professional,a,FrequenciaAssistencial.PRESENTE,a.getVersion())),()->businessStatus(correct(admin,a,FrequenciaAssistencial.PRESENTE,a.getVersion())))));assertEquals(count+1,audits.count());assertEquals(1,appointment(a.getId()).getVersion());}
    @RepeatedTest(2) void repeatedConcurrentNoopDoesNotCreateAuditOrVersion() throws Exception {var a=fact(SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(3),"08:00");var before=database();assertEquals(new RaceResult(2,0),race("E4-noop",List.of(()->businessStatus(correct(professional,a,FrequenciaAssistencial.FALTOU,a.getVersion())),()->businessStatus(correct(professional,a,FrequenciaAssistencial.FALTOU,a.getVersion())))));assertEquals(before,database());}
    @RepeatedTest(2) void correctionAndP05ReschedulePreserveSourceAndAudit() throws Exception {var a=fact(SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(3),"08:00");var booking=dto(patient,colleague,"08:30",TurnoEnum.MANHA,a.getId());long count=audits.count(),rows=appointments.count();assertEquals(new RaceResult(1,1),race("E4-reschedule",List.of(()->correct(a),()->post(booking))));var current=appointment(a.getId());assertEquals(count+(current.getFrequenciaAssistencial()==FrequenciaAssistencial.PRESENTE?1:0),audits.count());if(current.getSituacaoReserva()==SituacaoReserva.SUBSTITUIDA){assertEquals(FrequenciaAssistencial.FALTOU,current.getFrequenciaAssistencial());assertEquals(rows+1,appointments.count());}else{assertEquals(FrequenciaAssistencial.PRESENTE,current.getFrequenciaAssistencial());assertEquals(rows,appointments.count());}}
    @RepeatedTest(2) void genericCancelAlwaysLosesToKnownClinicalFact() throws Exception {var a=fact(SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(3),"08:00");long count=audits.count();assertEquals(new RaceResult(1,1),race("E4-cancel",List.of(()->correct(a),()->businessStatus(mvc.perform(patch("/api/agendamentos/"+a.getId()+"/status").param("novoStatus","CANCELADO").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse()))));assertEquals(FrequenciaAssistencial.PRESENTE,appointment(a.getId()).getFrequenciaAssistencial());assertEquals(count+1,audits.count());}
    @RepeatedTest(2) void correctionAndNewReservationShareProfessionalLock() throws Exception {date=LocalDate.now();tx(()->{capacity(professional,date,TurnoEnum.MANHA,10);return null;});var a=fact(SituacaoAtendimento.FALTOU,date,"08:00");long count=audits.count();assertEquals(new RaceResult(1,1),race("E4-create",List.of(()->correct(a),()->post(dto(other,professional,"08:00",TurnoEnum.MANHA,null)))));assertEquals(count+(appointment(a.getId()).getFrequenciaAssistencial()==FrequenciaAssistencial.PRESENTE?1:0),audits.count());assertEquals(1,tx(()->appointments.findAll().stream().filter(x->x.getUsuario().getId().equals(professional.getId())&&x.getDataAgendamento().equals(date)&&x.getHoraAtendimento().equals(LocalTime.of(8,0))&&Boolean.TRUE.equals(x.getOcupaVaga())).count()));}
    @RepeatedTest(2) void capacityChangeCannotInvalidateHistoricalCorrection() throws Exception {date=LocalDate.now();var config=tx(()->{capacity(professional,date,TurnoEnum.MANHA,10);return exceptions.findByUsuarioAndDataAndTurno(professional,date,TurnoEnum.MANHA).orElseThrow();});var a=fact(SituacaoAtendimento.FALTOU,date,"08:00");var result=race("E4-capacity",List.of(()->correct(a),()->businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/disponibilidade-config/excecoes").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(new DisponibilidadeExcecaoDTO(config.getId(),professional.getIdPublico(),date,TurnoEnum.MANHA,0)))).andReturn().getResponse())));assertTrue(result.equals(new RaceResult(2,0))||result.equals(new RaceResult(1,1)));assertEquals(FrequenciaAssistencial.PRESENTE,appointment(a.getId()).getFrequenciaAssistencial());assertEquals(1,jdbc.queryForObject("select count(*) from tb_auditoria_correcao_frequencia where agendamento_id=?",Integer.class,a.getId()));}
    @RepeatedTest(2) void subsequentBlockCannotInvalidateHistoricalCorrection() throws Exception {var day=LocalDate.now().minusDays(3);var a=fact(SituacaoAtendimento.FALTOU,day,"08:00");var result=race("E4-block",List.of(()->correct(a),()->businessStatus(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/bloqueioAgenda-config").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(new BloqueioAgendaDTO(null,professional.getIdPublico(),day,day,"Bloqueio sintético posterior ao atendimento.")))).andReturn().getResponse())));assertTrue(result.equals(new RaceResult(2,0))||result.equals(new RaceResult(1,1)));assertEquals(FrequenciaAssistencial.PRESENTE,appointment(a.getId()).getFrequenciaAssistencial());}
    @Test void secondProfessionalCannotAcquirePermissionThroughAConcurrentRequest() throws Exception {
        var a=fact(SituacaoAtendimento.FALTOU,LocalDate.now().minusDays(3),"08:00");long count=audits.count();var executor=java.util.concurrent.Executors.newFixedThreadPool(2);var ready=new java.util.concurrent.CountDownLatch(2);var start=new java.util.concurrent.CountDownLatch(1);var connections=java.util.concurrent.ConcurrentHashMap.<Integer>newKeySet();
        try{var futures=List.of(professional,colleague).stream().map(actor->executor.submit(()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(status->{connections.add(jdbc.queryForObject("select session_id()",Integer.class));ready.countDown();authenticate();try{assertTrue(start.await(10,java.util.concurrent.TimeUnit.SECONDS));int result=businessStatus(correct(actor,a,FrequenciaAssistencial.PRESENTE,a.getVersion()));if(result>=400)status.setRollbackOnly();return result;}catch(Exception e){throw new IllegalStateException(e);}finally{org.springframework.security.core.context.SecurityContextHolder.clearContext();}}))).toList();assertTrue(ready.await(10,java.util.concurrent.TimeUnit.SECONDS));start.countDown();assertEquals(200,futures.get(0).get(30,java.util.concurrent.TimeUnit.SECONDS));assertEquals(403,futures.get(1).get(30,java.util.concurrent.TimeUnit.SECONDS));assertEquals(2,connections.size());assertEquals(count+1,audits.count());System.out.println("E4_ROLE_RACE operations=2 confirmed=1 rejected=1 connections=2");}finally{start.countDown();executor.shutdownNow();assertTrue(executor.awaitTermination(10,java.util.concurrent.TimeUnit.SECONDS));}
    }
}
